import{_ as d,C as r,o as p,c as g,a3 as n,E as a,j as t,a as s}from"./chunks/framework.CZI2zymD.js";const L=JSON.parse('{"title":"Séance 9 — La rencontre avec la cliente","description":"","frontmatter":{"title":"Séance 9 — La rencontre avec la cliente","aside":false},"headers":[],"relativePath":"modules/02-conception/09-rencontre-avec-la-cliente.md","filePath":"modules/02-conception/09-rencontre-avec-la-cliente.md"}'),b={name:"modules/02-conception/09-rencontre-avec-la-cliente.md"};function m(h,e,v,q,f,_){const o=r("FigureUnePhraseDeuxProjets"),l=r("CeQuElleVeut"),i=r("FigureTroisSortes"),u=r("FigureRecit"),c=r("FigureDeLaQuestionAuRapport");return p(),g("div",null,[e[0]||(e[0]=n('<h1 id="seance-9-—-la-rencontre-avec-la-cliente" tabindex="-1">Séance 9 — La rencontre avec la cliente <a class="header-anchor" href="#seance-9-—-la-rencontre-avec-la-cliente" aria-label="Permalink to &quot;Séance 9 — La rencontre avec la cliente&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li><strong>Reconnaître</strong> ce que la cliente veut vraiment, derrière ce qu&#39;elle dit.</li><li><strong>Distinguer</strong> ce que le site doit faire, comment il doit le faire, et ce que la cliente doit décider.</li><li><strong>Mener</strong> une rencontre avec la cliente et en écrire le <strong>compte rendu</strong> tout de suite après.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La matière d&#39;abord, en grand groupe. Après la pause, la <strong>rencontre avec Mélanie</strong>, en grand groupe aussi, puis le compte rendu en équipe jusqu&#39;à la fin de la soirée.</p><ol><li>Retour sur le Lab 08</li><li>La partie 2 du cours</li><li>Étape 1 — Ce qu&#39;elle dit, ce qu&#39;elle veut</li><li>Activité 1 — La boulangerie, six phrases</li><li>Étape 2 — Trois sortes de réponses, et le récit utilisateur</li><li>Étape 3 — Mener la rencontre et écrire le compte rendu</li><li>Consignes du Lab 09 et à faire à la maison</li><li>Pause</li><li><strong>La rencontre avec Mélanie</strong>, en grand groupe (<a href="./../../labs/lab09-rencontre-avec-melanie">Lab 09</a>, partie 1)</li><li>Le compte rendu, en équipe (Lab 09, parties 2 et 3), jusqu&#39;à la fin de la soirée</li></ol><p>Le <strong>retour sur le Lab 09</strong> aura lieu au début de la séance 10.</p><hr><h2 id="retour-lab-08" tabindex="-1">Retour sur le Lab 08 <a class="header-anchor" href="#retour-lab-08" aria-label="Permalink to &quot;Retour sur le Lab 08 {#retour-lab-08}&quot;">​</a></h2><p>Dans le chat : <strong>le chiffre du lab qui vous a le plus surpris</strong>, et pourquoi.</p><hr><h2 id="partie-2" tabindex="-1">La partie 2 du cours <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;La partie 2 du cours {#partie-2}&quot;">​</a></h2><p>La partie 1 demandait : <strong>peut-on le faire, avec quoi, et combien ça coûte ?</strong> La partie 2 demande : <strong>qu&#39;est-ce qu&#39;on construit exactement, dans quel ordre, et pour quand ?</strong> Tout commence par ce soir : on ne construit bien que ce qu&#39;on a compris. Le plan de la partie est sur la <a href="./">page de présentation</a>.</p><hr><h2 id="ce-quelle-veut" tabindex="-1">Étape 1 sur 3 — Ce qu&#39;elle dit, ce qu&#39;elle veut <a class="header-anchor" href="#ce-quelle-veut" aria-label="Permalink to &quot;Étape 1 sur 3 — Ce qu&#39;elle dit, ce qu&#39;elle veut {#ce-quelle-veut}&quot;">​</a></h2><p><strong>La question.</strong> Une cliente parle de ce qu&#39;elle connaît : ce qu&#39;elle a vu ailleurs, ce qui l&#39;agace, ce qu&#39;on lui a conseillé. Comment trouver le besoin derrière ses mots ?</p><p><strong>La méthode, en trois gestes</strong>, sur une phrase tirée du mandat :</p>',17)),a(o),e[1]||(e[1]=n('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> On ne note pas la solution que la cliente propose : on note le besoin qu&#39;elle a confirmé.<br><strong>Où ça va.</strong> Ce soir, dans les questions que vous posez après une réponse de Mélanie, pour creuser. </div><h3 id="activite-1" tabindex="-1">Activité 1 — La boulangerie, six phrases <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — La boulangerie, six phrases {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min en équipe, puis 10 min de retour en grand groupe)</strong><br> On retrouve la boulangerie de la séance 8. À la première rencontre, la propriétaire a dit ces six phrases. <ol class="list-decimal pl-5"><li><strong>Pour chaque phrase</strong>, choisissez ce qu&#39;elle veut vraiment.</li><li><strong>Choisissez la sorte de réponse</strong> : ce que le site doit faire, comment il doit le faire, ou une décision que la cliente doit prendre.</li><li><strong>Cliquez sur « Vérifier »</strong> : pour chaque phrase, vous verrez la question à poser pour en être sûr.</li><li><strong>Copiez vos réponses</strong> avec le bouton, pour les garder.</li></ol><strong>Si vous bloquez :</strong> demandez-vous ce que les clients de la boulangerie feraient, concrètement, si la propriétaire obtenait ce qu&#39;elle dit.<br><strong>Pour le retour en groupe :</strong> quelle phrase cachait le plus une solution ? </div>',3)),a(l),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"trois-sortes",tabindex:"-1"},[s("Étape 2 sur 3 — Trois sortes de réponses, et le récit utilisateur "),t("a",{class:"header-anchor",href:"#trois-sortes","aria-label":'Permalink to "Étape 2 sur 3 — Trois sortes de réponses, et le récit utilisateur {#trois-sortes}"'},"​")],-1)),e[4]||(e[4]=t("p",null,[t("strong",null,"La question."),s(" Que faire de chaque réponse de Mélanie ?")],-1)),e[5]||(e[5]=t("p",null,[t("strong",null,"La méthode."),s(" On range chaque réponse dans une des trois sortes. Chacune a sa place dans votre travail.")],-1)),a(i),e[6]||(e[6]=t("p",null,[t("strong",null,"Le récit utilisateur."),s(" Ce que le site doit faire s'écrit du point de vue de la personne qui s'en sert, en une phrase de trois morceaux :")],-1)),a(u),e[7]||(e[7]=n('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Le « afin de » est la partie la plus importante : c&#39;est le besoin.<br><strong>Où ça va.</strong> Dans la fiche du Lab 09, puis dans les récits de la séance 10. </div><hr><h2 id="la-rencontre" tabindex="-1">Étape 3 sur 3 — Mener la rencontre et écrire le compte rendu <a class="header-anchor" href="#la-rencontre" aria-label="Permalink to &quot;Étape 3 sur 3 — Mener la rencontre et écrire le compte rendu {#la-rencontre}&quot;">​</a></h2><p><strong>La question.</strong> Neuf équipes et une seule cliente. Comment en sortir avec des réponses utiles, et ne pas les perdre ?</p><p><strong>Les règles de la rencontre.</strong></p><ol><li><strong>Une question à la fois</strong>, posée à voix haute par une personne de l&#39;équipe. L&#39;ordre des équipes est donné dans le chat; on fait plusieurs tours.</li><li><strong>Votre question a déjà été posée ?</strong> Passez à la suivante, ou posez une <strong>question de suivi</strong>, qui creuse une réponse déjà donnée : « Donc, si un client annule la veille, il est remboursé ? »</li><li><strong>Tout le monde note toutes les réponses</strong>, pas seulement celles de son équipe. Une réponse donnée à l&#39;équipe 3 peut changer votre devis.</li><li><strong>On ne vend pas de solution ce soir.</strong> On pose des questions; les choix seront dans la proposition.</li></ol><p>Rappel de la séance 8 :</p><table tabindex="0"><thead><tr><th style="text-align:left;">✕ À éviter</th><th style="text-align:left;">✓ À poser</th></tr></thead><tbody><tr><td style="text-align:left;">« Est-ce que vous aimez le bleu ? »</td><td style="text-align:left;">« Quelle politique d&#39;annulation voulez-vous ? » : <strong>une question, une décision</strong></td></tr><tr><td style="text-align:left;">« Avez-vous besoin d&#39;un mode hors ligne ? »</td><td style="text-align:left;">« Les guides doivent-ils voir la liste au quai, sans réseau ? » : <strong>dans ses mots à elle</strong></td></tr></tbody></table><p><strong>Le compte rendu, tout de suite après.</strong> Voici le chemin d&#39;une réponse de Mélanie, de votre question jusqu&#39;à la proposition :</p>',9)),a(c),e[8]||(e[8]=n('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> On note les mots de Mélanie, pas notre résumé : un chiffre, une date, un nom.<br><strong>Où ça va.</strong> Lab 09, parties 1 et 2, puis l&#39;évaluation 2 (voir l&#39;étape 4 de la figure). </div><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab09-rencontre-avec-melanie">Lab 09 — La rencontre avec Mélanie et son compte rendu</a>. Téléchargez la fiche <strong>avant la pause</strong> et gardez vos cinq questions du Lab 08 sous la main. Après la pause, on se retrouve tous dans la réunion du cours pour la rencontre. Après la rencontre, les équipes partent écrire le compte rendu.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><ul><li><strong>Terminer le compte rendu</strong> (Lab 09, partie 2), s&#39;il n&#39;est pas fini ce soir.</li><li><strong>Écrire la section 1.3 de l&#39;évaluation 2</strong> à partir de votre compte rendu : vos questions, les réponses de Mélanie, et ce qu&#39;elles changent.</li><li><strong>Ajuster vos sections 2, 4 et 5.2</strong> si une réponse les touche : un critère, une adaptation, une date du client.</li><li><strong>Lire la réponse écrite de Mélanie</strong> aux questions laissées en suspens ce soir. Elle l&#39;enverra à tout le groupe d&#39;ici le vendredi 27 novembre.</li></ul><hr><h2 id="avant-la-seance-10-2-decembre" tabindex="-1">Avant la séance 10 (2 décembre) <a class="header-anchor" href="#avant-la-seance-10-2-decembre" aria-label="Permalink to &quot;Avant la séance 10 (2 décembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses de l&#39;activité 1 dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 09 (<code>lab09-equipeN.docx</code>) dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Avoir un premier jet de la section 1.3 de l&#39;évaluation 2</span></label></li><li><label><input type="checkbox"><span class="check-text">Avoir choisi la réponse de Mélanie qui change le plus votre proposition (Lab 09, partie 3)</span></label></li></ul>',10))])}const T=d(b,[["render",m]]);export{L as __pageData,T as default};
